{
  "technical_and_design_decisions": [
    "Use Spring Cloud Stream Binder SPI to implement Azure Event Hubs connector (U1) and direct binding (U4).",
    "For direct binding, implement an in-process channel binder that connects modules without external messaging middleware.",
    "Expose REST APIs using Spring Boot controllers layered on existing stream/job service interfaces for xd-admin (U5).",
    "Provide ModuleRegistry stubs as a simple in-memory test implementation to allow mock stream creation (U6).",
    "For IPython Notebook integration (U2), integrate via Jupyter/IPython Kernel Gateway REST API to execute code and stream output.",
    "Preserve backward compatibility by keeping configuration directory layout and copying servers.yml during upgrade (U3).",
    "Implement in-memory stream definition repository using a ConcurrentHashMap backing the existing repository interface (U8).",
    "Relocate spring-cloud-stream-modules using git subtree and update Gradle/Maven build and package names (U7)."
  ],
  "assumptions": [
    "Developer is experienced with Spring XD, Spring Cloud Stream, and Spring Boot.",
    "Target platform is Java 8 (Spring XD era), not Java 17, because the user stories reference legacy Spring XD/Spring Cloud Data components.",
    "Azure Event Hubs Java SDK is available and compatible with the chosen Spring Cloud Stream version.",
    "An external IPython Notebook / Jupyter server is available for integration testing; no custom Python kernel is embedded.",
    "All work is done by a single developer on a single branch with continuous integration already in place.",
    "Effort includes unit and integration testing but excludes external code review cycles and production deployment.",
    "Existing build system (Gradle or Maven) will be reused without major infrastructure changes."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Analysis and detailed design",
      "activity_description": "Review user stories U1-U8, define architecture, and set up project branches and build configuration for new modules.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Azure Event Hubs connector (U1)",
      "activity_description": "Implement read/write modules for Azure Event Hubs using Azure SDK and Spring Cloud Stream binder, including configuration and unit tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "IPython Notebook integration (U2)",
      "activity_description": "Develop integration with IPython Notebook to allow interactive real-time data computations from Spring XD.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Upgrade config preservation (U3)",
      "activity_description": "Modify installation/upgrade scripts and code to retain older installation directories and reuse servers.yml configurations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Direct module binding (U4)",
      "activity_description": "Add a direct-binding transport option in Spring Cloud Stream to connect modules in-process without messaging middleware.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "REST API for xd-admin (U5)",
      "activity_description": "Build REST API foundation using Spring Boot to perform CRUD operations on streaming and batch pipelines via xd-admin.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "ModuleRegistry stubs (U6)",
      "activity_description": "Create stub/fake ModuleRegistry implementation to enable mock stream creation through registry APIs.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Relocate stream modules (U7)",
      "activity_description": "Move spring-cloud-stream-modules from s-c-s to s-c repository, update build files, package names, and clean up s-c-s.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "In-memory stream definition repository (U8)",
      "activity_description": "Implement an in-memory StreamDefinitionRepository that does not require external storage, for development use.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration testing and defect fixing",
      "activity_description": "Perform end-to-end integration testing of all new features, fix defects, and verify backward compatibility.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Documentation and examples",
      "activity_description": "Write user guides, migration notes, REST API docs, and example configurations for the new capabilities.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 58
  }
}

